module.exports = function(RED) {
    function CampaignAnalyticsNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.on('input', async function(msg) {
            // For now, just log summary (can be extended with Redis aggregation)
            console.log(`[Analytics] Campaign: ${msg.campaignId || 'unknown'}`);
            node.status({ fill: "blue", shape: "ring", text: "Analytics Logged" });
            node.send(msg);
        });
    }
    RED.nodes.registerType("campaign-analytics", CampaignAnalyticsNode);
};